import java.util.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
/** A source-only may-be-uninitialized analysis. This never reads reference Code or frames. */
public final class InitializedSourceNewProof implements Opcodes {
 static void need(boolean b,String s){ExecutableVerify.need(b,"source_initialized_NEW_"+s);}
 static Map<String,Object> prove(MethodNode q,Frame<SourceValue>[] frames,Map<AbstractInsnNode,Integer> rawIndex,Set<AbstractInsnNode> selected)throws Exception {
  var ops=LeafSource.ops(q);var ord=new IdentityHashMap<AbstractInsnNode,Integer>();for(int p=0;p<ops.size();p++)ord.put(ops.get(p),p);
  var sourceNews=new TreeMap<Integer,TypeInsnNode>();var accesses=new ArrayList<Map<String,Object>>();var accessOrigins=new IdentityHashMap<AbstractInsnNode,Set<Integer>>();
  for(var n:selected){need(n instanceof VarInsnNode,"selected_projection_is_real_local_access");var v=(VarInsnNode)n;var f=frames[rawIndex.get(n)];need(f!=null,"projection_reachable_in_actual_source_CFG");boolean store=LocalLifetimes.store(n.getOpcode());var value=store?f.getStack(f.getStackSize()-1):f.getLocal(v.var);var origins=new TreeSet<Integer>();
   for(var producer:value.insns)if(producer.getOpcode()==NEW){need(producer instanceof TypeInsnNode&&ord.containsKey(producer),"NEW_marker_is_an_actual_source_instruction");int id=ord.get(producer);sourceNews.put(id,(TypeInsnNode)producer);origins.add(id);}
   if(!origins.isEmpty()){accessOrigins.put(n,origins);accesses.add(LeafSource.map("source_access_opcode_ordinal",ord.get(n),"opcode",n.getOpcode(),"source_NEW_opcode_ordinals",origins));}
  }
  if(sourceNews.isEmpty())return LeafSource.map("kind","initialized_actual_source_NEW_projection","source_NEW_origins",List.of(),"source_projection_accesses",List.of(),"original_target_Code_frames_used",false,"source_only",true);
  need((long)ops.size()*sourceNews.size()<=12000000L,"finite_CFG_origin_resource_frontier");
  var ctors=new TreeMap<Integer,List<Integer>>();for(int p=0;p<ops.size();p++)if(ops.get(p) instanceof MethodInsnNode c&&c.getOpcode()==INVOKESPECIAL&&c.name.equals("<init>")){
   var f=frames[rawIndex.get(c)];if(f==null)continue;var args=Type.getArgumentTypes(c.desc);need(Type.getReturnType(c.desc).getSort()==Type.VOID,"constructor_real_void_descriptor");int receiver=f.getStackSize()-args.length-1;need(receiver>=0,"constructor_receiver_is_real_source_stack_cell");var value=f.getStack(receiver);
   for(var producer:value.insns)if(producer.getOpcode()==NEW&&ord.containsKey(producer)&&sourceNews.containsKey(ord.get(producer))){int id=ord.get(producer);need(value.insns.size()==1&&value.size==1,"constructor_receiver_one_stable_source_allocation");need(c.owner.equals(sourceNews.get(id).desc),"constructor_owner_equals_exact_fresh_source_NEW_type");ctors.computeIfAbsent(id,k->new ArrayList<>()).add(p);}
  }
  var compact=new HashMap<Integer,Integer>();var constructorKill=new HashMap<Integer,Integer>();var witnesses=new ArrayList<Object>();int count=0;for(var e:sourceNews.entrySet()){
   var sites=ctors.get(e.getKey());need(sites!=null&&sites.size()==1,"one_actual_matching_source_constructor_per_NEW");int id=count++;compact.put(e.getKey(),id);need(constructorKill.put(sites.get(0),id)==null,"constructor_initializes_one_distinct_allocation");var c=(MethodInsnNode)ops.get(sites.get(0));witnesses.add(LeafSource.map("source_NEW_opcode_ordinal",e.getKey(),"type",e.getValue().desc,"source_constructor_opcode_ordinal",sites.get(0),"constructor_owner",c.owner,"constructor_descriptor",c.desc));
  }
  var normal=new ArrayList<List<Integer>>();var exceptional=new ArrayList<List<Integer>>();for(int p=0;p<ops.size();p++){normal.add(new ArrayList<>());exceptional.add(new ArrayList<>());var n=ops.get(p);var succ=normal.get(p);if(n instanceof JumpInsnNode j){need(j.getOpcode()!=JSR,"JSR_not_supported");succ.add(ExecutableVerify.target(q,j.label));if(j.getOpcode()!=GOTO)succ.add(p+1);}else if(n instanceof TableSwitchInsnNode s){succ.add(ExecutableVerify.target(q,s.dflt));for(var l:s.labels)succ.add(ExecutableVerify.target(q,l));}else if(n instanceof LookupSwitchInsnNode s){succ.add(ExecutableVerify.target(q,s.dflt));for(var l:s.labels)succ.add(ExecutableVerify.target(q,l));}else if(!CFGSource.exit(n.getOpcode()))succ.add(p+1);for(int to:succ)need(to>=0&&to<ops.size(),"normal_successor_is_real_source_opcode");}
  for(var h:q.tryCatchBlocks){int start=ExecutableVerify.target(q,h.start),end=ExecutableVerify.target(q,h.end),handler=ExecutableVerify.target(q,h.handler);need(start>=0&&start<end&&end<=ops.size()&&handler>=0&&handler<ops.size(),"actual_source_exception_region_endpoints");for(int p=start;p<end;p++)exceptional.get(p).add(handler);}
  BitSet[] pending=new BitSet[ops.size()];pending[0]=new BitSet(count);var queue=new ArrayDeque<Integer>();var queued=new boolean[ops.size()];queue.add(0);queued[0]=true;int updates=0;long limit=(long)ops.size()*(count+1L)*8L+16;
  while(!queue.isEmpty()){int p=queue.remove();queued[p]=false;need(++updates<=limit,"finite_monotone_completion_fixpoint");var before=pending[p];var after=(BitSet)before.clone();Integer generated=compact.get(p);if(generated!=null)after.set(generated);Integer kill=constructorKill.get(p);if(kill!=null)after.clear(kill);for(int to:normal.get(p))merge(to,after,pending,queued,queue);for(int to:exceptional.get(p))merge(to,before,pending,queued,queue);}
  var explicitPending=new ArrayList<Object>();for(var e:accessOrigins.entrySet()){int p=ord.get(e.getKey());need(pending[p]!=null,"all_projection_points_reached_by_independent_source_CFG");for(int origin:e.getValue())if(pending[p].get(compact.get(origin))){need(ExplicitSourceNewDomain.allowed(q,sourceNews.get(origin)),"constructor_success_or_explicit_source_NEW_domain_on_every_allocation_to_projection_path_"+origin+"_"+p);explicitPending.add(LeafSource.map("source_access_opcode_ordinal",p,"source_NEW_opcode_ordinal",origin,"exact_fresh_source_bound_NEW",true,"mandatory_full_consumer_producer_and_final_uninitialized_identity_frame_proofs",true));}}
  return LeafSource.map("kind","initialized_actual_source_NEW_projection","source_NEW_origins",witnesses,"source_projection_accesses",accesses,"source_only",true,"original_target_Code_frames_used",false,"all_projection_NEW_origins_initialized_on_every_reaching_path",explicitPending.isEmpty(),"explicit_source_pending_NEW_projection_witnesses",explicitPending,"pending_projection_scope_requires_all_final_source_NEW_identity_and_frame_proofs",!explicitPending.isEmpty(),"normal_constructor_completion_clears_pending_origin",true,"exceptional_constructor_edges_keep_preoperation_pending_state",true,"NEW_reexecution_sets_pending_origin_again",true,"may_uninitialized_join_is_union_absent_allocations_are_safe",true,"source_cfg_fixpoint_updates",updates,"all_retained_NEW_constructor_consumers_and_effects_still_checked_by_full_transport_proof",true);
 }
 static void merge(int to,BitSet state,BitSet[] pending,boolean[] queued,ArrayDeque<Integer> queue){boolean changed;if(pending[to]==null){pending[to]=(BitSet)state.clone();changed=true;}else{var old=(BitSet)pending[to].clone();pending[to].or(state);changed=!old.equals(pending[to]);}if(changed&&!queued[to]){queued[to]=true;queue.add(to);}}
}
